// Der Agent liefert Text, kein JSON. Hier wird das vereinbarte Format ANTWORT/QUELLEN
// zerlegt und - wichtiger - geprueft, ob wirklich eine belegte Antwort vorliegt.
// Warum die zweite Pruefung: Ein Sprachmodell haelt sich in etwa 1 von 50 Faellen nicht
// an sein Format oder liefert eine fluessig formulierte Antwort ohne jede Quelle.
// Genau diese Faelle sind die gefaehrlichen, weil sie besonders ueberzeugend klingen.
const anfrage = $('Frage entgegennehmen').first().json.body || {};
const roh = String($input.first().json.output ?? $input.first().json.text ?? '').trim();

const antwortTreffer = roh.match(/ANTWORT:\s*([\s\S]*?)(?:\n\s*QUELLEN:|$)/i);
const quellenTreffer = roh.match(/QUELLEN:\s*([\s\S]*)$/i);

const antwort = (antwortTreffer ? antwortTreffer[1] : roh).trim();
const quellenRoh = (quellenTreffer ? quellenTreffer[1] : '').trim();

const quellen = quellenRoh
  .split(/[,;\n]/)
  .map((q) => q.trim())
  .filter((q) => q && !/^(keine|none|-|n\/a)$/i.test(q));

// Formulierungen, mit denen der Agent laut Prompt die Fehlanzeige meldet.
const fehlanzeige = /(finde ich nichts|keine passenden|nicht in den (hinterlegten )?unterlagen|liegt mir nicht vor)/i;

const wissensluecke = quellen.length === 0 || fehlanzeige.test(antwort) || antwort.length < 15;

return [{
  json: {
    frage: String(anfrage.frage || '').trim(),
    abteilung: String(anfrage.abteilung || 'unbekannt').trim(),
    antwort: wissensluecke
      // Einheitliche, ehrliche Formulierung statt der jeweiligen Improvisation des Modells.
      ? 'Dazu finde ich nichts in den hinterlegten Unterlagen. Bitte an die Fachabteilung wenden — die Frage wurde als Wissensluecke vermerkt.'
      : antwort,
    quellen: quellen.join(', ') || 'KEINE',
    treffer: quellen.length,
    wissensluecke,
    hinweis: 'Diese Antwort wurde von einem KI-Assistenten aus internen Dokumenten erzeugt. Im Zweifel gilt das Originaldokument.',
    zeitpunkt: new Date().toISOString(),
  },
}];

